package dev.kelmagic.artifact;
import java.util.*;
import dev.kelmagic.*;
import dev.kelmagic.server.*;
import net.minecraft.core.*;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.*;
import net.minecraft.world.item.context.UseOnContext;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.phys.*;
public class ArtifactItem extends Item {
    public final String artifact;
    public ArtifactItem(String id,Properties p){super(p);artifact=id;}
    @Override public void appendHoverText(ItemStack s,TooltipContext c,List<Component> lines,TooltipFlag f){lines.add(Component.translatable("kelmagic.artifact.tip."+artifact));if(artifact.equals("spare_heart_medallion"))lines.add(Component.translatable("kelmagic.artifact.stored",String.format(java.util.Locale.ROOT,"%.1f",ArtifactData.charge(s,10)),10));if(artifact.equals("dusk_dew_ring"))lines.add(Component.translatable("kelmagic.artifact.dew",(int)(100*ArtifactData.charge(s,1))));var t=ArtifactData.get(s);if(t.contains("KelWitness"))lines.add(Component.translatable("kelmagic.artifact.witness_note",t.getString("KelWitnessFrom"),t.getString("KelWitness")));if(t.getBoolean("KelFlame"))lines.add(Component.translatable("kelmagic.artifact.bottle_full"));}
    @Override public boolean canPerformAction(ItemStack stack,net.neoforged.neoforge.common.ItemAbility ability){return artifact.equals("alien_phrase_shield")&&net.neoforged.neoforge.common.ItemAbilities.DEFAULT_SHIELD_ACTIONS.contains(ability)||super.canPerformAction(stack,ability);}
    @Override public int getUseDuration(ItemStack s,LivingEntity e){return artifact.equals("alien_phrase_shield")||artifact.equals("still_volley_orb")?72000:0;}
    @Override public UseAnim getUseAnimation(ItemStack s){return artifact.equals("alien_phrase_shield")?UseAnim.BLOCK:artifact.equals("still_volley_orb")?UseAnim.BOW:UseAnim.NONE;}
    @Override public InteractionResultHolder<ItemStack> use(Level l,Player player,InteractionHand hand){var stack=player.getItemInHand(hand);if(l.isClientSide)return InteractionResultHolder.pass(stack);if(!(player instanceof ServerPlayer p)||p.getCooldowns().isOnCooldown(this)||!p.isAlive()||p.isSpectator())return InteractionResultHolder.fail(stack);
        switch(artifact){case "alien_phrase_shield","still_volley_orb"->{if(!ArtifactRuntime.canCast(p))return InteractionResultHolder.fail(stack);p.startUsingItem(hand);return InteractionResultHolder.consume(stack);}case "reverse_echo_bracelet"->{if(ArtifactWorld.echo(p)){p.getCooldowns().addCooldown(this,200);ArtifactVisuals.sound(p.serverLevel(),p.position(),"artifact_chime",.75f);}return InteractionResultHolder.success(stack);}case "reflected_path_fan"->{if(ArtifactCombat.fan(p)){p.getCooldowns().addCooldown(this,30);stack.hurtAndBreak(1,p,LivingEntity.getSlotForHand(hand));return InteractionResultHolder.success(stack);}return InteractionResultHolder.fail(stack);}case "wayback_chalk"->{if(p.isShiftKeyDown()){ArtifactData.edit(stack,t->t.remove("KelMarks"));return InteractionResultHolder.success(stack);}}default->{}}
        return InteractionResultHolder.pass(stack);
    }
    @Override public InteractionResult useOn(UseOnContext c){if(c.getLevel().isClientSide)return InteractionResult.SUCCESS;if(!(c.getPlayer() instanceof ServerPlayer p)||p.isSpectator())return InteractionResult.FAIL;var l=p.serverLevel();var at=c.getClickedPos();var stack=c.getItemInHand();if(p.getCooldowns().isOnCooldown(this)||!p.getAbilities().mayBuild||!l.mayInteract(p,at)||!ArtifactWorld.allowed(p,at)||!p.mayUseItemAt(at,c.getClickedFace(),stack))return InteractionResult.FAIL;
        switch(artifact){case "wayback_chalk"->{var tag=ArtifactData.get(stack);if(!tag.hasUUID("KelMarkOwner")||!tag.getUUID("KelMarkOwner").equals(p.getUUID()))tag.remove("KelMarks");var list=tag.getList("KelMarks",net.minecraft.nbt.Tag.TAG_COMPOUND);var mark=new net.minecraft.nbt.CompoundTag();mark.putLong("Pos",at.asLong());mark.putString("Dim",l.dimension().location().toString());if(list.size()>=32)list.remove(0);list.add(mark);tag.put("KelMarks",list);tag.putUUID("KelMarkOwner",p.getUUID());stack.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(tag));p.getCooldowns().addCooldown(this,5);return InteractionResult.SUCCESS;}
        case "stopped_season_secateurs"->{if(!(l.getBlockState(at).getBlock() instanceof BonemealableBlock))return InteractionResult.PASS;if(ArtifactSeasons.get(l).toggle(at,p.getUUID(),l.getBlockState(at))){ArtifactVisuals.ring(l,Vec3.atCenterOf(at),.45,0xe7c77d,12);ArtifactVisuals.sound(l,Vec3.atCenterOf(at),"artifact_chime",.8f);stack.hurtAndBreak(1,p,LivingEntity.getSlotForHand(c.getHand()));return InteractionResult.SUCCESS;}return InteractionResult.FAIL;}
        case "living_water_can"->{if(!ArtifactRuntime.canCast(p)||ArtifactSeasons.locked(l,at)||!ArtifactRuntime.spend(p,1))return InteractionResult.FAIL;boolean grown=BoneMealItem.applyBonemeal(new ItemStack(Items.BONE_MEAL),l,at,p);if(!grown){ArtifactRuntime.addMana(p,1);return InteractionResult.PASS;}p.getCooldowns().addCooldown(this,40);ArtifactVisuals.ring(l,Vec3.atCenterOf(at),.6,0x8fe2ba,16);stack.hurtAndBreak(1,p,LivingEntity.getSlotForHand(c.getHand()));return InteractionResult.SUCCESS;}
        case "quiet_flame_bottle"->{var data=ArtifactData.get(stack);if(!data.getBoolean("KelFlame")){var old=l.getBlockState(at);if(!old.is(MagicContent.MAGIC_FIRE.get()))return InteractionResult.PASS;var snap=net.neoforged.neoforge.common.util.BlockSnapshot.create(l.dimension(),l,at);if(net.neoforged.neoforge.common.NeoForge.EVENT_BUS.post(new net.neoforged.neoforge.event.level.BlockEvent.BreakEvent(l,at,old,p)).isCanceled())return InteractionResult.FAIL;l.removeBlock(at,false);ArtifactData.edit(stack,t->{t.putBoolean("KelFlame",true);t.putInt("KelFlameScale",old.getValue(dev.kelmagic.block.MagicFireBlock.SCALE));});}else{var pos=at.relative(c.getClickedFace());if(!l.hasChunkAt(pos)||!l.getWorldBorder().isWithinBounds(pos)||!l.mayInteract(p,pos)||!p.mayUseItemAt(pos,c.getClickedFace(),stack)||!ArtifactWorld.allowed(p,pos)||!l.getBlockState(pos).canBeReplaced())return InteractionResult.FAIL;var next=MagicContent.MAGIC_FIRE.get().stateAt(l,pos).setValue(dev.kelmagic.block.MagicFireBlock.SCALE,Math.clamp(data.getInt("KelFlameScale"),0,12));if(!next.canSurvive(l,pos))return InteractionResult.FAIL;var snap=net.neoforged.neoforge.common.util.BlockSnapshot.create(l.dimension(),l,pos);if(!l.setBlockAndUpdate(pos,next))return InteractionResult.FAIL;if(net.neoforged.neoforge.event.EventHooks.onBlockPlace(p,snap,Direction.UP)){snap.restore();return InteractionResult.FAIL;}ArtifactData.edit(stack,t->{t.remove("KelFlame");t.remove("KelFlameScale");});}p.getCooldowns().addCooldown(this,10);ArtifactVisuals.sound(l,Vec3.atCenterOf(at),"artifact_chime",1.1f);return InteractionResult.SUCCESS;}
        case "hanging_path_staff"->{if(!ArtifactRuntime.canCast(p)||!l.getBlockState(at).isFaceSturdy(l,at,Direction.UP))return InteractionResult.FAIL;var dir=p.getDirection();int made=0;for(int i=1;i<=8;i++){var pos=at.relative(dir,i);if(!l.hasChunkAt(pos)||!l.isInWorldBounds(pos)||!l.getWorldBorder().isWithinBounds(pos)||!l.getBlockState(pos).isAir()||!l.mayInteract(p,pos)||!ArtifactWorld.allowed(p,pos)||!p.mayUseItemAt(pos,Direction.UP,stack))break;if(!ArtifactRuntime.spend(p,.5))break;var snapshot=net.neoforged.neoforge.common.util.BlockSnapshot.create(l.dimension(),l,pos);if(!l.setBlockAndUpdate(pos,ArtifactContent.BRIDGE.get().defaultBlockState()))break;if(net.neoforged.neoforge.event.EventHooks.onBlockPlace(p,snapshot,Direction.UP)){snapshot.restore();ArtifactRuntime.addMana(p,.5);break;}if(l.getBlockEntity(pos) instanceof ArtifactBlockEntity be){be.owner=p.getUUID();be.expires=l.getGameTime()+200;be.changed();l.scheduleTick(pos,ArtifactContent.BRIDGE.get(),200);}made++;}if(made==0)return InteractionResult.FAIL;ArtifactVisuals.sound(l,Vec3.atCenterOf(at),"path_weave",.9f);p.getCooldowns().addCooldown(this,60);stack.hurtAndBreak(1,p,LivingEntity.getSlotForHand(c.getHand()));return InteractionResult.SUCCESS;}
        default->{return InteractionResult.PASS;}}
    }
}
